-- ----------------------------
-- Table structure for smkj_attachment
-- ----------------------------
DROP TABLE IF EXISTS `smkj_attachment`;
CREATE TABLE `smkj_attachment` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '附件编号',
  `name` varchar(128) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '附件名',
  `type` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '附件类型(jpg,png,doc,xls,ppt...)',
  `size` int(11) DEFAULT NULL COMMENT '附件大小 单位KB',
  `url` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '附件地址',
  `status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0表示待删除附件 1表示任务附件',
  `user_id` int(11) NOT NULL COMMENT '所属用户id',
  `disk` varchar(20) COLLATE utf8_unicode_ci NOT NULL COMMENT '文件存储驱动',
  `created_at` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_attachment
-- ----------------------------

