  `auth_big_ico` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '认证大图标',
  `auth_open` tinyint(4) DEFAULT NULL COMMENT '认证是否开启 0：未开启 1：已开启',
  `list_order` tinyint(4) DEFAULT NULL COMMENT '认证排序',
  PRIMARY KEY (`auth_code`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

