  `description` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '行为操作详情描述',
  `url` varchar(255) COLLATE utf8_unicode_ci NOT NULL COMMENT '行为操作访问路径',
  `class` varchar(255) COLLATE utf8_unicode_ci NOT NULL COMMENT '行为操作执行调用类名',
