  `teaching_experience` varchar(50) DEFAULT NULL COMMENT '教学经验',
  `professional_license` varchar(100) DEFAULT NULL COMMENT '职业证书',
  `certified` tinyint(1) DEFAULT '0' COMMENT 'TEFL或TESOL认证      0:无  1；TEFL、2：TESOL',
  `start_time` tinyint(1) DEFAULT NULL COMMENT '开始时间',
  `work_location` varchar(50) DEFAULT NULL COMMENT '首选工作地点',
  `work_area` varchar(50) DEFAULT NULL COMMENT '首选工作区域',
  `teaching_subject` tinyint(1) DEFAULT NULL COMMENT '首选教学科目（ESL、英语、STEM、AP课程、IB课程、A-level课程）',
  `start_salary` tinyint(1) DEFAULT NULL COMMENT '开始工资',
  `resume` varchar(200) DEFAULT NULL COMMENT '简历附件',
  `status` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of smkj_resume
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_roles
-- ----------------------------
DROP TABLE IF EXISTS `smkj_roles`;
CREATE TABLE `smkj_roles` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '角色编号',
  `name` varchar(32) COLLATE utf8_unicode_ci NOT NULL COMMENT '角色名称（别名）',
  `display_name` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '角色名称',
  `description` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '角色描述',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `roles_name_unique` (`name`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_roles
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_role_user
-- ----------------------------
DROP TABLE IF EXISTS `smkj_role_user`;
CREATE TABLE `smkj_role_user` (
  `user_id` int(10) unsigned NOT NULL COMMENT 'user_id',
  `role_id` int(10) unsigned NOT NULL COMMENT '角色id',
  PRIMARY KEY (`user_id`,`role_id`),
  KEY `role_user_role_id_foreign` (`role_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

