-- Records of smkj_role_user
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_substation
-- ----------------------------
DROP TABLE IF EXISTS `smkj_substation`;
CREATE TABLE `smkj_substation` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `district_id` int(11) NOT NULL COMMENT '地区id',
  `name` varchar(20) COLLATE utf8_unicode_ci NOT NULL COMMENT '站点名称',
  `status` tinyint(4) NOT NULL DEFAULT '2' COMMENT '状态 1=>开启  2=>关闭',
  `sort` tinyint(4) NOT NULL DEFAULT '0' COMMENT '排序',
  `created_at` timestamp NULL DEFAULT NULL COMMENT '站点创建时间',
  `updated_at` timestamp NULL DEFAULT NULL COMMENT '站点修改时间',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_substation
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_system_log
-- ----------------------------
DROP TABLE IF EXISTS `smkj_system_log`;
CREATE TABLE `smkj_system_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `log_type` tinyint(4) NOT NULL COMMENT '日志类型',
  `uid` int(11) NOT NULL COMMENT '操作用户ID',
  `username` varchar(32) COLLATE utf8_unicode_ci NOT NULL COMMENT '用户名',
  `user_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '用户类型',
  `log_content` varchar(255) COLLATE utf8_unicode_ci NOT NULL COMMENT '日志详情',
  `IP` varchar(32) COLLATE utf8_unicode_ci NOT NULL COMMENT 'IP地址',
  `created_at` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=61 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_system_log
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_tag_user
-- ----------------------------
DROP TABLE IF EXISTS `smkj_tag_user`;
CREATE TABLE `smkj_tag_user` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tag_id` int(11) NOT NULL COMMENT '标签编号',
  `uid` int(11) NOT NULL COMMENT '用户ID',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=32 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_tag_user
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_users
-- ----------------------------
DROP TABLE IF EXISTS `smkj_users`;
CREATE TABLE `smkj_users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '用户编号',
  `name` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '用户名',
  `email` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '用户邮箱',
  `mobile` varchar(20) COLLATE utf8_unicode_ci NOT NULL DEFAULT '' COMMENT '用户手机注册',
  `email_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '用户邮箱认证状态0：未认证1：待验证2：已经认证',
  `password` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '用户密码',
  `alternate_password` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '支付密码',
  `salt` varchar(10) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '随机码',
  `status` tinyint(4) DEFAULT NULL COMMENT '账户状态 0：未激活 1：已激活 2：禁用',
  `overdue_date` timestamp NULL DEFAULT NULL COMMENT '找回密码邮件过期时间',
  `validation_code` varchar(10) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '找回密码随机码',
  `expire_date` timestamp NULL DEFAULT NULL COMMENT '重置密码邮件过期时间',
  `reset_password_code` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '重置密码验证随机码',
  `remember_token` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `last_login_time` timestamp NULL DEFAULT NULL COMMENT '最后一次登录时间',
  `source` tinyint(4) NOT NULL DEFAULT '1' COMMENT '注册来源 1-来自pc 2-来自手机',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_users
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_user_attachment
-- ----------------------------
DROP TABLE IF EXISTS `smkj_user_attachment`;
CREATE TABLE `smkj_user_attachment` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT '用户id',
  `attachment_id` int(11) NOT NULL DEFAULT '0' COMMENT '附件记录id',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_user_attachment
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_user_detail
-- ----------------------------
DROP TABLE IF EXISTS `smkj_user_detail`;
CREATE TABLE `smkj_user_detail` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '用户详情编号',
  `uid` int(11) NOT NULL COMMENT '用户编号',
  `realname` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '真实姓名',
  `realname_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '表示真实姓名是否公开 0表示不公开 1表示公开',
  `sex` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0表示女 1表示男',
  `mobile` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '手机号码',
  `mobile_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0表示不公开 1表示公开',
  `nickname` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'app端用户昵称',
  `qq` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '用户qq',
  `qq_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'qq是否公开 0表示不公开 1表示公开',
  `wechat` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '用户微信号',
  `wechat_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'qq是否公开 0表示不公开 1表示公开',
  `card_number` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '身份证号码',
  `province` int(11) DEFAULT NULL COMMENT '用户省份',
  `city` int(11) DEFAULT NULL COMMENT '用户城市',
  `area` int(11) DEFAULT NULL COMMENT '用户地区',
  `avatar` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '用户头像',
  `autograph` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '个人签名',
  `introduce` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '个人简介',
  `sign` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '个人标签',
  `employee_praise_rate` int(11) NOT NULL DEFAULT '0' COMMENT '做为服务商的好评数量',
  `employer_praise_rate` int(11) NOT NULL DEFAULT '0' COMMENT '做为雇主的好评数量',
  `receive_task_num` int(11) DEFAULT NULL COMMENT '承接任务数量',
  `publish_task_num` int(11) DEFAULT NULL COMMENT '发布任务数量',
  `shop_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '店铺状态: -1.管理员禁用店铺 0.未开启店铺 1.开启店铺 2.关闭店铺',
  `balance` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '用户资产余额',
  `balance_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '资产冻结 0表示未冻结 1表示资金被冻结',
  `last_login_time` timestamp NULL DEFAULT NULL COMMENT '最后一次登录时间',
  `backgroundurl` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '空间个人资料背景图片',
  `alternate_tips` tinyint(4) NOT NULL DEFAULT '0' COMMENT '支付提示 0：提示 1：不提示',
  `employee_num` int(11) NOT NULL DEFAULT '0' COMMENT '累计雇佣量',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_detail_uid_unique` (`uid`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_user_detail
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_user_focus
-- ----------------------------
DROP TABLE IF EXISTS `smkj_user_focus`;
CREATE TABLE `smkj_user_focus` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `uid` int(11) NOT NULL DEFAULT '0' COMMENT '用户id',
  `focus_uid` int(11) NOT NULL DEFAULT '0' COMMENT '被关注者id',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

-- ----------------------------
-- Records of smkj_user_focus
-- ----------------------------

-- ----------------------------
-- Table structure for smkj_website
-- ----------------------------
DROP TABLE IF EXISTS `smkj_website`;
CREATE TABLE `smkj_website` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '联系我们',
  `logo` varchar(100) DEFAULT NULL COMMENT '网站logo',
  `phone` varchar(20) DEFAULT NULL COMMENT '电话',
  `email` varchar(50) DEFAULT NULL COMMENT '邮箱',
  `weChat` varchar(50) DEFAULT NULL COMMENT '微信',
  `location` varchar(100) DEFAULT NULL COMMENT '地址',
  `qrcode` varchar(200) DEFAULT NULL COMMENT '二维码',
  `address` varchar(200) DEFAULT NULL COMMENT '地址（英文）',
  `copyright` varchar(100) DEFAULT NULL COMMENT '版权信息',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of smkj_website
